import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"PRD","description":"","frontmatter":{},"headers":[],"relativePath":"skill/PRD.md","filePath":"skill/PRD.md","lastUpdated":null}'),o={name:"skill/PRD.md"};function h(i,a,p,n,d,m){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="prd" tabindex="-1">PRD <a class="header-anchor" href="#prd" aria-label="Permalink to &quot;PRD&quot;">​</a></h1><h2 id="定义1" tabindex="-1">定义<a href="http://www.woshipm.com/pmd/3319375.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#定义1" aria-label="Permalink to &quot;定义[1]&quot;">​</a></h2><p>PRD是产品汪思考后的产品方案呈现载体，主要用于沟通研发、测试、设计、运营等，也会用于存档便于查看和回溯。</p><p>PRD 主要是给开发人员、UI 设计人员、测试人员等看的，目的是让开发人员知道如何按照产品经理的思路为需求撰写代码，让UI 设计人员知道他们需要输出哪些UI 设计稿，让测试人员知道测试用例中需要包含哪些测试点。PRD 的撰写侧重点是需求描述、需求逻辑、需求原型。PRD 是所有产品经理都会接触到的，也是产品经理平时写得最多的文档，所以大家一定要好好研究。</p><h3 id="战略层——用户需求-产品目标" tabindex="-1">战略层——用户需求&amp;产品目标 <a class="header-anchor" href="#战略层——用户需求-产品目标" aria-label="Permalink to &quot;战略层——用户需求&amp;产品目标&quot;">​</a></h3><p>将需求背景、用户需求写在开头，后续撰写都要围绕这个核心，相当于定了方向，也可以指引阅读者更好更快的了解需求。 不管是定量目标还是定性目标，都要落实到PRD上，这是整个项目团队工作的预期成果。</p><h3 id="范围层——功能规格-内容需求" tabindex="-1">范围层——功能规格&amp;内容需求 <a class="header-anchor" href="#范围层——功能规格-内容需求" aria-label="Permalink to &quot;范围层——功能规格&amp;内容需求&quot;">​</a></h3><p>战略层中明确了用户需求和产品目标后，范围层就要确定做哪些功能、提供什么内容来实现产品目标，可以将各个功能点以及它们的优先级用脑图或excel画出来（工具随意），相当于把整个需求分拆成各个模块，便于理解和评估工作。</p><h3 id="结构层——交互设计-信息架构" tabindex="-1">结构层——交互设计&amp;信息架构 <a class="header-anchor" href="#结构层——交互设计-信息架构" aria-label="Permalink to &quot;结构层——交互设计&amp;信息架构&quot;">​</a></h3><p>范围层把需求分拆之后，结构层再把各个部分用流程图或思维脑图连接起来，让阅读者能抽象出产品的使用流程或信息架构。</p><p>偏交易、工具的产品需求可以使用流程图，偏内容的产品需求可以使用思维脑图，此处放一个点餐交易的局部流程图，仅做示例参考。</p><h3 id="框架层——界面设计-导航设计" tabindex="-1">框架层——界面设计&amp;导航设计 <a class="header-anchor" href="#框架层——界面设计-导航设计" aria-label="Permalink to &quot;框架层——界面设计&amp;导航设计&quot;">​</a></h3><p>结构层将需求分拆模块，框架层梳理整体流程，相信这时候PRD读者已经对需求有了清晰的思路，框架层主要对每个模块或页面的逻辑、布局做详细阐述。</p><h3 id="表现层——视觉设计" tabindex="-1">表现层——视觉设计 <a class="header-anchor" href="#表现层——视觉设计" aria-label="Permalink to &quot;表现层——视觉设计&quot;">​</a></h3><p>表现层主要包括但不限于视觉、听觉、触觉等内容，需要做一些高保真的设计，建议与UED、用户体验部门联合产出，这里不做过多展开。</p><h2 id="过程2" tabindex="-1">过程<a href="http://www.woshipm.com/pmd/3516749.html" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#过程2" aria-label="Permalink to &quot;过程[2]&quot;">​</a></h2><p>先找研发对一下需求，连接上下游的关系。然后再写，把层次关系梳理出现，再用图表或流程图表现。拆分组块业务逻辑，梳理业务上下游。</p><p>目录：</p><ol><li>产品背景</li><li>名词解释</li><li>产品综述</li><li>用户故事</li><li>需求详述</li><li>评审记录</li><li>其他问题描述</li></ol><h3 id="产品背景" tabindex="-1">产品背景 <a class="header-anchor" href="#产品背景" aria-label="Permalink to &quot;产品背景&quot;">​</a></h3><h4 id="背景概述" tabindex="-1">背景概述 <a class="header-anchor" href="#背景概述" aria-label="Permalink to &quot;背景概述&quot;">​</a></h4><p>含义解释：背景概述是用简单的语言大概概括一下大的背景，让人知道我们本次要讲的内容大概是什么。</p><p>描述正文：官网为用户提供产品试用，目前，完整的试用流程如下：</p><p>用户在官网进行注册，填写申请试用表单。商务（运营）在管理后台，对用户的申请进行授权操作（允许/拒绝）。</p><p>注释：这样的背景描述，是将云官网，本次的产品需求，用业务流程串联起来，从前端到后端。从业务流程出发，将业务串联起来，这是一种非常好的方式。用一个事件，将涉及的所有产品功能都串联起来，让本次讨论有主线。</p><p>一般来说，这段话的作用在于让人阅读后明白我们为什么要花时间做这件事，以及明白了这件事的意义所在。重点在WHY，关于WHY的重要性，大家可以看一个演讲叫做How great leaders inspire action。</p><p>既然是完善和优化，那么产品经理就需要向运营、向研发证明，为什么这样的修改，相较于原来的流程，更好。</p><p>Example: <a href="http://www.woshipm.com/pd/4167090.html" target="_blank" rel="noreferrer">http://www.woshipm.com/pd/4167090.html</a></p><h2 id="ai产品" tabindex="-1">AI产品 <a class="header-anchor" href="#ai产品" aria-label="Permalink to &quot;AI产品&quot;">​</a></h2><p>二者的差异主要集中在需求内容的部分。而需求内容这方面的差异又因PM角色的不同而有所不同。</p><h2 id="测试完整性3" tabindex="-1">测试完整性<a href="http://www.woshipm.com/pmd/21446.html" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#测试完整性3" aria-label="Permalink to &quot;测试完整性[3]&quot;">​</a></h2><p>现在你有一个PRD草稿，你需要测试它的完整性。工程师是否可以充分了解并达到目标？OA Team（质量管理团队）是否有足够的信息来做出测试计划，是否可以开始做案例？</p><p>当投资人或相关人审核了PRD，确定了各个需要说明的方面，所有的问题得到解决，现在你就可以按PRD进行产品开发。</p><h2 id="管理产品3" tabindex="-1">管理产品<a href="http://www.woshipm.com/pmd/21446.html" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#管理产品3" aria-label="Permalink to &quot;管理产品[3]&quot;">​</a></h2><p>解决所有PRD中存在问题，如果不在PRD中就写进去。你的任务就是迅速解决问题并记录在PRD。</p><p>如果你做了你的工作并准备记录在PRD，项目审查就会变得非常简单，因为任何一个部份都历历在目。</p><p>记住PRD是一个“活”的文件，在要跟踪记录在产品开发期间的所有功能过程。最后你会发现很多额外的东西，如果你认为是必要的就在PRD中写进。</p><p>confluence：这个不多说了，非常好用的一款产品PRD在线编辑软件。<a href="http://www.woshipm.com/pmd/913343.html" target="_blank" rel="noreferrer">4</a></p><h2 id="cod评分表方法" tabindex="-1">COD评分表方法 <a class="header-anchor" href="#cod评分表方法" aria-label="Permalink to &quot;COD评分表方法&quot;">​</a></h2><h2 id="信息架构" tabindex="-1">信息架构 <a class="header-anchor" href="#信息架构" aria-label="Permalink to &quot;信息架构&quot;">​</a></h2><p>组织系统、标签系统、导航系统、搜索系统</p>',41)])])}const P=e(o,[["render",h]]);export{c as __pageData,P as default};
